// Table unifiée : fusionne compteRefMap (4 chiffres), fallback3 (3) et fallback2 (2)
// dans un seul dictionnaire indexé par longueur de préfixe, une fois pour toutes.
var LIASSE_PREFIX_TABLES = null;
function liasseGetPrefixTables(){
    if(LIASSE_PREFIX_TABLES) return LIASSE_PREFIX_TABLES;
    var byLen = {};
    function ingest(map){
        if(!map) return;
        for(var key in map){
            if(!map.hasOwnProperty(key)) continue;
            var len = key.length;
            if(!byLen[len]) byLen[len] = {};
            byLen[len][key] = map[key];
        }
    }
    ingest(LIASSE_DATA.compteRefMap);
    ingest(LIASSE_DATA.fallback3);
    ingest(LIASSE_DATA.fallback2);
    LIASSE_PREFIX_TABLES = byLen;
    return byLen;
}

// Résout un numéro de compte de balance (2 à N chiffres, le PCG SYSCOHADA officiel
// s'arrête à 4 chiffres mais les balances réelles subdivisent souvent jusqu'à 5, 6
// chiffres ou plus pour le suivi auxiliaire — ex: 411100023, 4457120001).
// Principe : correspondance par préfixe le plus long. On part de la longueur réelle
// du numéro de compte (ou 6, la profondeur SYSCOHADA usuelle, si plus long) et on
// raccourcit chiffre par chiffre jusqu'à trouver une entrée connue, sans jamais
// descendre sous 2 chiffres (niveau classe+sous-classe). Ainsi un compte à 6, 7, 8
// chiffres retombe automatiquement sur son compte de 4 chiffres du PCG dès que
// celui-ci existe, sans troncature arbitraire ni table à maintenir par longueur.
// Somme des comptes rattachés à un REF donné (ex: 'N' ou 'N1'), pour une colonne
// ('brut','amort' pour ACTIF ; 'net' pour PASSIF/RESULTAT), avec la convention de signe
// SD-SC (débiteur) pour brut/charges, SC-SD (créditeur) pour amort/passif/produits.
// 'which' permet de choisir le solde d'OUVERTURE (od/oc) ou de CLOTURE (sd/sc, défaut) —
// c'est cette bascule qui permet de réutiliser exactement le même moteur ACTIF/PASSIF
// pour calculer les variations du TFT (méthode indirecte).
// ---------- ACTIF / PASSIF : résolution récursive (postes détail + totaux) ----------
function liasseResolveTree(ex, lines, sensLeafNet, mapByRef, which){
    var memo = {};
    function resolve(ref){
        if(memo[ref]) return memo[ref];
        var line = mapByRef[ref];
        var res;
        if(line.children){
            res = {brut:0, amort:0, net:0};
            line.children.forEach(function(childRef){
                var cv = resolve(childRef);
                res.brut += cv.brut; res.amort += cv.amort; res.net += cv.net;
            });
        } else {
            var brut = liasseSumByRef(ex, ref, 'brut', 'SD-SC', which);
            var amort = liasseSumByRef(ex, ref, 'amort', 'SC-SD', which);
            var net = liasseSumByRef(ex, ref, 'net', sensLeafNet, which);
            // Une ligne n'a QUE brut/amort (ACTIF) OU net (PASSIF) selon la table de mapping ;
            // les deux approches sont additionnées car un seul des deux sera non-nul en pratique.
            res = {brut: brut, amort: amort, net: (brut - amort) + net};
        }
        memo[ref] = res;
        return res;
    }
    var out = {};
    lines.forEach(function(l){ out[l.ref] = resolve(l.ref); });
    return out;
}

function liasseGetActif(ex, which){
    var mapByRef = {};
    LIASSE_DATA.actifLines.forEach(function(l){ mapByRef[l.ref] = l; });
    return liasseResolveTree(ex, LIASSE_DATA.actifLines, 'SD-SC', mapByRef, which);
}
function liasseGetPassif(ex, resultatNetOverride, which){
    var mapByRef = {};
    LIASSE_DATA.passifLines.forEach(function(l){ mapByRef[l.ref] = l; });
    var vals = liasseResolveTree(ex, LIASSE_DATA.passifLines, 'SC-SD', mapByRef, which);
    // Le résultat net de l'exercice (CJ) doit provenir du calcul RESULTAT (XI), pas du solde
    // du compte 13x qui n'est en général pas encore soldé/affecté dans la balance en cours d'audit.
    if(typeof resultatNetOverride === 'number'){
        vals.CJ = {brut:0, amort:0, net: resultatNetOverride};
        // recalcule les totaux qui dépendent de CJ
        LIASSE_DATA.passifLines.forEach(function(l){
            if(l.children && l.children.indexOf('CJ') === -1 && l.children.indexOf('CP') === -1) return;
        });
        var byRef = {}; LIASSE_DATA.passifLines.forEach(function(l){ byRef[l.ref] = l; });
        function recompute(ref){
            var line = byRef[ref];
            if(!line || !line.children) return vals[ref];
            var brut=0, amort=0, net=0;
            line.children.forEach(function(c){ var v = recompute(c); brut+=v.brut; amort+=v.amort; net+=v.net; });
            vals[ref] = {brut:brut, amort:amort, net:net};
            return vals[ref];
        }
        recompute('DZ');
    }
    return vals;
}
